	out = strings.TrimSuffix(out, "")
	out = strings.ReplaceAll(out, "-", "-")
	out = strings.ReplaceAll(out, "~", "~")
	out = strings.ReplaceAll(out, "?", "?")
	out = strings.ReplaceAll(out, "\\", "\\")
	out = filepath.ToSlash(out)
	out = strings.Join(strings.Split(out, "/"), "/")
	out = strings.TrimPrefix(out, "")
	if len(out) == 0 {
		return out
	}
	return out
}

