// Temporary reproduction test for issue: '#' in links causes them to be truncated.
package hugolib

import (
	"testing"
)

func TestReproMatrix(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name   string
		config string
	}{
		{"sectionslug", "[permalinks]\ns1 = '/:section/:slug'\n"},
		{"dated", "[permalinks]\nposts = '/posts/:year/:month/:slug/'\n"},
		{"dated-noslash", "[permalinks]\nposts = '/posts/:year/:month/:slug'\n"},
		{"plain", "[permalinks]\nposts = '/posts/:slug/'\n"},
	}

	for _, c := range cases {
		files := `
-- hugo.toml --
` + c.config + `
-- layouts/_default/single.html --
{{ .Title }}
-- layouts/_default/list.html --
{{ range site.Pages }}{{ .RelPermalink }}|{{ end }}
-- content/posts/hash-in-title.md --
---
title: 'Newsletter #4'
date: 2024-04-04T12:27:52-07:00
---
Foo
`
		b := Test(t, files)
		b.AssertFileExists("public/posts/2024/04/newsletter-#4/index.html", true)
	}
}

// Temporary reproduction test for issue: '#' in links causes them to be truncated.
package hugolib

import (
	"testing"
)

func TestReproMatrix(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name   string
		config string
		expect string
	}{
		{"sectionslug", "[permalinks]\nposts = '/:section/:slug'\n", "public/posts/newsletter-#4/index.html"},
		{"dated", "[permalinks]\nposts = '/posts/:year/:month/:slug/'\n", "public/posts/2024/04/newsletter-#4/index.html"},
		{"dated-noslash", "[permalinks]\nposts = '/posts/:year/:month/:slug'\n", "public/posts/2024/04/newsletter-#4/index.html"},
		{"plain", "[permalinks]\nposts = '/posts/:slug/'\n", "public/posts/newsletter-#4/index.html"},
	}

	for _, c := range cases {
		files := `
-- hugo.toml --
` + c.config + `
-- layouts/_default/single.html --
{{ .Title }}
-- layouts/_default/list.html --
{{ range site.Pages }}{{ .RelPermalink }}|{{ end }}
-- content/posts/hash-in-title.md --
---
title: 'Newsletter #4'
date: 2024-04-04T12:27:52-07:00
---
Foo
`
		b := Test(t, files)
		b.AssertFileExists(c.expect, true)
	}
}
